int shifts = 0;
for (int i = 1; i < items.Length; i++)
{
    int picked = items[i];
    int j = i - 1;
    while (j >= 0 && items[j] > picked)
    {
        items[j + 1] = items[j];
        j--;
        shifts++;
    }
    items[j + 1] = picked;
}
foreach (int item in items) { Console.WriteLine(item); }
