    int l = start;
    int r = middle;
    int count = 0;
    for (int i = start; i < end; i++)
    {
        bool fromLeft = r == end;
        if (!fromLeft && l < middle)
        {
            count++;
            fromLeft = values[l] <= values[r];
        }
        if (fromLeft) { workspace[i] = values[l]; l++; }
        else { workspace[i] = values[r]; r++; }
    }
    for (int i = start; i < end; i++) { values[i] = workspace[i]; }
    return count;
}

