int[] heap = { 3, 8, 5, 12, 0 };
int size = 4;
int added = 1;
int index = size;
heap[index] = added;
size++;
int swaps = 0;
while (index > 0)
{
    int parent = (index - 1) / 2;
    if (heap[parent] <= heap[index]) { break; }
    int temporary = heap[parent];
    heap[parent] = heap[index];
    heap[index] = temporary;
    index = parent;
    swaps++;
}
for (int i = 0; i < size; i++) { Console.WriteLine(heap[i]); }
Console.WriteLine(swaps);

